<?php
require __DIR__.'/app.php';$u=require_auth();$pdo=db();$business=null;if($u['role']==='owner'){$q=$pdo->prepare('SELECT * FROM businesses WHERE id=?');$q->execute([$u['business_id']]);$business=$q->fetch();}$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(isset($_POST['business_name'])){require_owner();$name=trim((string)$_POST['business_name']);$legal=trim((string)($_POST['legal_name']??''));$currency=strtoupper(trim((string)$_POST['currency']));$kind=(string)($_POST['gst_registration_type']??'Unregistered');$gstin=strtoupper(trim((string)($_POST['gstin']??'')));$state=trim((string)($_POST['state']??''));$code=trim((string)($_POST['state_code']??''));if(!$name||!preg_match('/^[A-Z]{3}$/',$currency))$error='Enter a business name and three-letter currency code.';elseif(!in_array($kind,['Regular','Composition','Unregistered'],true))$error='Choose a valid GST registration type.';elseif($kind==='Regular'&&(!preg_match('/^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][1-9A-Z]Z[0-9A-Z]$/',$gstin)||!preg_match('/^[0-9]{2}$/',$code)||substr($gstin,0,2)!==$code||$state===''))$error='A regular GST profile needs a valid GSTIN, state, and matching two-digit state code.';else{$pdo->prepare('UPDATE businesses SET name=?,legal_name=?,currency=?,gst_registration_type=?,gstin=?,address=?,city=?,state=?,state_code=?,postal_code=? WHERE id=?')->execute([$name,$legal?:null,$currency,$kind,$gstin?:null,trim((string)($_POST['address']??''))?:null,trim((string)($_POST['city']??''))?:null,$state?:null,$code?:null,trim((string)($_POST['postal_code']??''))?:null,$u['business_id']]);audit('business.profile.update',$name);flash('Business profile saved.');redirect('settings.php');}}elseif(isset($_POST['current_password'])){$q=$pdo->prepare('SELECT password_hash FROM users WHERE id=?');$q->execute([$u['id']]);$hash=$q->fetchColumn();$new=(string)($_POST['new_password']??'');if(!password_verify((string)$_POST['current_password'],$hash)||strlen($new)<12||$new!==(string)($_POST['confirm_password']??''))$error='Current password must match; the new password must be at least 12 characters and match confirmation.';else{$pdo->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($new,PASSWORD_DEFAULT),$u['id']]);audit('account.password.change');session_regenerate_id(true);flash('Password changed.');redirect('settings.php');}}}
$q=$pdo->prepare('SELECT event,detail,created_at FROM activity_logs WHERE user_id=? ORDER BY created_at DESC LIMIT 8');$q->execute([$u['id']]);$logs=$q->fetchAll();page_start('Settings','settings');?>
<style>.settings-grid{display:grid;grid-template-columns:220px 1fr;gap:14px}.settings-nav,.settings-panel{background:#fff;border:1px solid #edf0f2;border-radius:9px;padding:14px}.settings-nav a{display:flex;gap:9px;padding:10px 8px;border-radius:6px;color:#687483;font-size:10px}.settings-nav a.active{background:#eaf5fc;color:#258bcb}.settings-panel h2{font:650 14px var(--display);margin:0 0 4px}.settings-panel>p{color:#929ca7;font-size:10px;margin:0 0 17px}.settings-panel .stack-form{max-width:650px}.settings-panel section{padding:13px 0;border-top:1px solid #eff1f3}.settings-panel section strong{font-size:11px}.settings-panel section p{font-size:10px;color:#919ba6;margin:4px 0}.setup-hint{background:#f5f9fc;padding:12px;border-radius:7px;font-size:10px;color:#73808d}.settings-panel .gst-fields{display:grid;grid-template-columns:1fr 1fr;gap:10px}.settings-panel label{display:block;color:#596574;font-size:10px;font-weight:600}.settings-panel input,.settings-panel select{display:block;width:100%;margin-top:5px;height:36px;border:1px solid #e5e9ed;border-radius:6px;padding:0 9px;font-size:11px}.settings-panel .wide{grid-column:1/-1}@media(max-width:700px){.settings-grid{grid-template-columns:1fr}.settings-nav{display:flex;overflow:auto;gap:5px}.settings-nav a{white-space:nowrap}.settings-panel .gst-fields{grid-template-columns:1fr}.settings-panel .wide{grid-column:auto}}</style>
<div class="section-head"><div><span class="eyebrow">WORKSPACE</span><h1>Settings</h1><p>Keep your workspace details and account up to date.</p></div></div><?php if($error):?><div class="flash error"><?=e($error)?></div><?php endif?><div class="settings-grid"><nav class="settings-nav"><a class="active" href="#business"><i class="ti ti-building"></i> Business profile</a><a href="#account"><i class="ti ti-user"></i> Your account</a><a href="#security"><i class="ti ti-shield"></i> Security</a><a href="#backup"><i class="ti ti-database-export"></i> Backup</a><a href="#activity"><i class="ti ti-history"></i> Activity log</a><a href="docs/installation.md"><i class="ti ti-book"></i> Help & setup</a></nav><div class="settings-panel"><h2 id="business">Business and GST profile</h2><p>GST details are saved on new invoices. Confirm registration type, state code and registration details with your tax adviser.</p><?php if($u['role']==='owner'):?><form method="post" class="stack-form"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><div class="gst-fields"><label>Business name<input name="business_name" required value="<?=e($business['name'])?>"></label><label>Legal name<input name="legal_name" value="<?=e($business['legal_name']??'')?>"></label><label>Currency code<input name="currency" maxlength="3" required value="<?=e($business['currency'])?>"></label><label>GST registration type<select name="gst_registration_type"><option <?=($business['gst_registration_type']??'Unregistered')==='Regular'?'selected':''?>>Regular</option><option <?=($business['gst_registration_type']??'Unregistered')==='Composition'?'selected':''?>>Composition</option><option <?=($business['gst_registration_type']??'Unregistered')==='Unregistered'?'selected':''?>>Unregistered</option></select></label><label>GSTIN<input name="gstin" maxlength="15" value="<?=e($business['gstin']??'')?>"></label><label>State<input name="state" value="<?=e($business['state']??'')?>"></label><label>GST state code<input name="state_code" maxlength="2" pattern="[0-9]{2}" value="<?=e($business['state_code']??'')?>"></label><label>City<input name="city" value="<?=e($business['city']??'')?>"></label><label class="wide">Business address<input name="address" value="<?=e($business['address']??'')?>"></label><label>Postal code<input name="postal_code" value="<?=e($business['postal_code']??'')?>"></label></div><button class="button primary">Save business and GST profile</button></form><?php else:?><div class="setup-hint">Business and GST profile settings are managed by the Owner.</div><?php endif?><section><strong>Workspace access</strong><p>Role: <?=e(ucfirst($u['role']))?></p></section><section id="account"><strong>Your account</strong><p><?=e($u['name'])?> · <?=e($u['email'])?></p></section><section id="security"><strong>Change password</strong><p>Use at least 12 characters and avoid reusing another account password.</p><form method="post" class="stack-form"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><label>Current password<input type="password" name="current_password" required></label><label>New password<input type="password" name="new_password" minlength="12" required></label><label>Confirm new password<input type="password" name="confirm_password" minlength="12" required></label><button class="button secondary">Update password</button></form></section><section id="backup"><strong>Business data backup and restore</strong><p>Download a JSON snapshot of business records and line items. Password hashes are excluded. Restore replaces operational records only; user accounts stay unchanged. A protected recovery copy is taken before restore.</p><?php if($u['role']==='owner'):?><a class="button secondary" href="backup.php"><i class="ti ti-download"></i> Download backup</a> <a class="button secondary" href="restore.php"><i class="ti ti-database-import"></i> Restore backup</a><?php else:?><p>Backup downloads are restricted to the Owner.</p><?php endif?></section><section id="activity"><strong>Recent account activity</strong><?php if(!$logs):?><p>No activity recorded yet.</p><?php else:foreach($logs as $l):?><p><b><?=e($l['event'])?></b> · <?=e($l['detail'])?> <span class="help-text">· <?=fmt_date($l['created_at'])?></span></p><?php endforeach;endif?></section></div></div><?php page_end();
